  function startCanvasEditText(id: string) {
    const element = elementById.get(id);
    const knownGroup =
      element?.groupId &&
      groups.some((group) => group.id === element.groupId)
        ? element.groupId
        : null;
    if (knownGroup && activeGroupIdRef.current !== knownGroup) {
      applyGroupSelectionState(
        planGroupEnter({ items: elements, groups, clickedId: id })
      );
      announceDrawingShortcut("그룹 내부 편집 · 다시 더블클릭하면 텍스트를 편집해요");
      return;
    }
    void startEditText(id);
  }

  async function startEditText(id: string) {
    const el = elementById.get(id);
    if (!el || (el.type !== "text" && el.type !== "bubble" && el.type !== "sticker")) return;
    // Start the optional editor chunk before the collaboration lock round trip. Typical networked
    // sessions therefore pay no post-lock module waterfall, while the initial Studio bundle stays
    // focused on the canvas shell.
    preloadStudioTextEditOverlay();
    const mutationTicket = captureStudioMutationTicket();
    const targetPageId = activePage.id;
    const targetMasterEditMode = masterEditMode;
    if (!(await beginLiveResourceEditAsync([id], "text-edit"))) return;
    if (
      !canApplyStudioMutation(mutationTicket) ||
      currentPageIdRef.current !== targetPageId ||
      masterEditModeRef.current !== targetMasterEditMode
    ) {
      endLiveResourceEdit();
      return;
    }
    setEditing({ id });
  }

  function commitEditText(finalValue: string) {
    try {
      if (editing) {
        const el = elementById.get(editing.id);
        // 말풍선은 텍스트가 넘치지 않게 높이를 자동 확장(수동으로 키운 크기는 보존) — 단,
        // autoShrinkText(크기 고정 모드)가 켜져 있으면 높이는 건드리지 않는다(렌더 시점에
        // fitBubbleFontSize가 폰트 크기를 알아서 줄인다).
        //
        // 측정 노드는 **실제 렌더 KText와 완전히 같은 속성**으로 만들어야 한다. 예전에는
        // lineHeight 1.1(실제 1.25~1.4)·fontStyle 미지정(실제 bold)·width `-36`(실제 패딩
        // 2×bHPad)·높이 여유 `+28`(실제 상하 패딩 합)이라 블록 높이를 항상 과소평가했고,
        // Konva.Text는 고정 height를 넘는 줄을 경고 없이 버려 대사가 조용히 잘렸다.
        // 기본값·패딩은 전부 studio-bubble-text-fit 단일 소스에서 가져온다.
        let height: number | undefined;
        if (el && el.type === "bubble" && !el.autoShrinkText) {
          const fontSize = resolveBubbleFontSize(el.fontSize);
          const fontFamily = resolveBubbleFontFamily(el.font);
          const fontStyle = resolveBubbleFontStyle(el.fontStyle);
          const lineHeight = resolveBubbleLineHeight({
            lineHeight: el.lineHeight,
            vertical: el.vertical,
            theme: webtoonTheme,
          });
          const letterSpacing = bubbleLetterSpacing(webtoonTheme);
          if (el.vertical) {
            // 세로쓰기는 열 조판이라 가로 KText로 잴 수 없다 — 세로 코어를 쓰는 공유 계산.
            height = fitBubbleBoxHeightToText({
              text: finalValue,
              boxWidth: el.width,
              fontSize,
              fontFamily,
              fontStyle,
              lineHeight,
              letterSpacing,
              vertical: true,
              // blockAlign은 열 안 정렬일 뿐이라 "들어가느냐" 판정에는 영향이 없다(코어 계약).
              minHeight: el.height,
            });
          } else {
            const measure = new KonvaRuntime.Text({
              text: finalValue || " ",
              width: bubbleTextBoxWidth(el.width, fontSize),
              fontSize,
              fontFamily,
              fontStyle,
              align: el.align ?? "center",
              lineHeight,
              letterSpacing,
            });
            height = Math.max(
              el.height,
              Math.ceil(measure.height()) + bubbleVerticalPaddingTotal(fontSize)
            );
            measure.destroy();
          }
        }
        patchEl(editing.id, { text: finalValue, ...(height !== undefined ? { height } : {}) } as Partial<El>);
      }
      setEditing(null);
    } finally {
      endLiveResourceEdit();
    }
  }

  function cancelEditText() {
    setEditing(null);
    endLiveResourceEdit();
  }

  async function captureReadyStageForPage(page: PageState): Promise<Konva.Stage> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 캡처할 수 있어요.");
    }
    const {
      collectStudioCaptureAssetSources,
      waitForStudioCaptureReady,
    } = await loadStudioCaptureReadinessRuntime();
    return waitForStudioCaptureReady({
      pageId: page.id,
      getRenderedPageId: () => {
        const committed = captureCommitRef.current;
        return committed.exporting && !committed.masterEditMode ? committed.pageId : null;
      },
      getStage: () => stageRef.current,
      assetSources: collectStudioCaptureAssetSources(page, master),
    });
  }

  async function captureReadyStageForHistoryPage(
    page: PageState,
    historyIndex: number
  ): Promise<Konva.Stage> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 타임랩스를 만들 수 있어요.");
    }
    const {
      collectStudioCaptureAssetSources,
      waitForStudioCaptureReady,
    } = await loadStudioCaptureReadinessRuntime();
    const renderKey = `${page.id}:${historyIndex}`;
    return waitForStudioCaptureReady({
      pageId: renderKey,
      getRenderedPageId: () => {
        const committed = captureCommitRef.current;
        return committed.timelapse && !committed.masterEditMode
          ? `${committed.pageId}:${committed.historyIndex}`
          : null;
      },
      getStage: () => stageRef.current,
      assetSources: collectStudioCaptureAssetSources(page, master),
    });
  }

