  // 타임랩스 — pagesHi를 히스토리 인덱스로 스크러빙하며 각 단계를 캡처한다. 고정 sleep 대신
  // historyIndex까지 포함한 실제 React/Konva commit을 기다리고, 끝나면 원래 페이지·히스토리로 복구한다.
  async function captureTimelapseStep(historyIndex: number, targetWidth: number): Promise<MotionCutImage> {
    const snapshot = pagesHistory[historyIndex];
    const targetPage = snapshot?.find((page) => page.id === currentPageId) ?? snapshot?.[0];
    if (!targetPage) throw new Error("타임랩스로 캡처할 페이지를 찾을 수 없어요.");
    setPagesHi(historyIndex);
    setCurrentPageId(targetPage.id);
    const stage = await captureReadyStageForHistoryPage(targetPage, historyIndex);
    const pixelRatio = targetWidth / CANVAS_W / effScale;
    const canvas = stage.toCanvas({ pixelRatio });
    return { source: canvas, width: canvas.width, height: canvas.height };
  }

  function handleTimelapseRecordingStart() {
    invalidateAdvancedFillWork("타임랩스 캡처를 시작해 미적용 채우기 미리보기를 취소했습니다.");
    clearAdvancedFillTapGesture();
    setAdvancedFillActive(false);
    timelapseOriginalHiRef.current = pagesHi;
    timelapseOriginalPageIdRef.current = currentPageId;
    timelapseOriginalMasterEditModeRef.current = masterEditMode;
    setMasterEditMode(false);
    preserveStudioViewBeforeCapture();
    setTimelapseCapturing(true);
  }

  function handleTimelapseRecordingEnd() {
    setPagesHi(timelapseOriginalHiRef.current);
    if (timelapseOriginalPageIdRef.current) {
      setCurrentPageId(timelapseOriginalPageIdRef.current);
    }
    setMasterEditMode(timelapseOriginalMasterEditModeRef.current);
    setTimelapseCapturing(false);
  }

  // 현재 페이지 → 벡터 SVG 직렬화(요소 데이터 필요라 여기서 조립). 다운로드·고지는 내보내기 패널이 담당.
  async function exportCurrentPageToSvg(): Promise<SvgExportResult> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 SVG로 내보낼 수 있어요.");
    }
    const [
      { runStudioSvgExportWorker },
      { projectStudioLinked3dRasterSourcesForPortableExport },
    ] = await Promise.all([
      loadStudioSvgExportWorkerClientModule(),
      import("./studio-linked-3d-portable-raster-projection"),
    ]);
    const portableElements = await projectStudioLinked3dRasterSourcesForPortableExport(elements);
    const { result } = await runStudioSvgExportWorker({
      width: CANVAS_W,
      height: canvasH,
      bg,
      bgGrad,
      transparentBg: exportTransparent,
      elements: portableElements as unknown as readonly SvgExportEl[],
      groups,
      theme: webtoonTheme,
    });
    return result;
  }

  async function exportCurrentPageToInkMl(): Promise<StudioInkMlExportResult> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 InkML로 내보낼 수 있어요.");
    }
    const { exportStudioInkMl } = await import("./studio-inkml-interchange");
    const pageGroups = activePage.groups ?? EMPTY_LAYER_GROUPS;
    const drawElements = activePage.elements.filter(
      (element): element is DrawEl =>
        element.type === "draw" && !isEffectivelyHidden(element, pageGroups),
    );
    return exportStudioInkMl(drawElements);
  }

  async function exportCurrentPageToWillV1(): Promise<StudioWillV1PageExportResult> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 WILL v1으로 내보낼 수 있어요.");
    }
    const pageGroups = activePage.groups ?? EMPTY_LAYER_GROUPS;
    const drawElements = activePage.elements.filter(
      (element): element is DrawEl =>
        element.type === "draw" && !isEffectivelyHidden(element, pageGroups),
    );
    return exportStudioPageToWillV1({
      width: CANVAS_W,
      height: canvasH,
      title,
      elements: drawElements,
    });
  }

  // 현재 페이지 → 요소별 레이어를 가진 PSD. exportPagePsd 는 숨김 요소를 스스로 거르지 않으므로
  // (숨긴 요소는 렌더 시점에 Konva 노드 자체가 없어 캡처가 불가능 — 모듈 JSDoc 계약) 여기서
  // isEffectivelyHidden 기준으로 미리 걸러 넘긴다.
  async function exportCurrentPageToPsd(): Promise<PsdExportResult> {
    if (!ensureSharedDocumentAvailableForExport()) {
      throw new Error("공동 문서를 불러온 뒤 PSD로 내보낼 수 있어요.");
    }
    const originalMasterEditMode = masterEditMode;
    setSelectedId(null);
    setMasterEditMode(false);
    preserveStudioViewBeforeCapture();
    hideStrokeGuide();
    setIsExporting(true);
    try {
      const [stage, { exportPagePsd }] = await Promise.all([
        captureReadyStageForPage(activePage),
        loadStudioPsdExportModule(),
      ]);
      const pageGroups = activePage.groups ?? EMPTY_LAYER_GROUPS;
      const visible = activePage.elements.filter(
        (element) => !isEffectivelyHidden(element, pageGroups)
      );
      return exportPagePsd(
        stage,
        visible as unknown as PsdExportEl[],
        CANVAS_W,
        canvasH,
        effScale,
        {
          scale: exportScale,
          background: { color: bg, gradient: bgGrad },
        }
      );
    } finally {
      setMasterEditMode(originalMasterEditMode);
      setIsExporting(false);
    }
  }

