  async function downloadAiPublicSummary(summary: unknown) {
    if (!ensureSharedDocumentAvailableForExport()) return;
    const { downloadBlob } = await import("./export/studio-export");
    downloadBlob(
      new Blob([JSON.stringify(summary, null, 2)], { type: "application/json" }),
      `${(title.trim() || "toonspectrum").replace(/[\\/:*?"<>|]+/g, "-")}-ai-public-summary.json`
    );
  }

  function currentStudioProjectSnapshot(options: {
    readonly pendingStrokeCommits?: {
      readonly pageId: string;
      readonly strokes: readonly DrawEl[];
    } | null;
    readonly recoveredMasterStroke?: DrawEl | null;
  } = {}): StudioProjectSnapshot {
    // Immediate pointerup commits advance these refs before React renders, closing the same-task
    // route/pagehide gap where this render's `pages` could still be one stroke behind.
    const pendingBatch = options.pendingStrokeCommits === undefined
      ? pendingStrokeCommitsRef.current
      : options.pendingStrokeCommits;
    const snapshotEligiblePendingStrokes = pendingBatch?.strokes.filter((stroke) => (
      !selectedGpuStrokeRequiresFinalReceipt(stroke.id)
      || hasExactSelectedGpuFinalReceipt(stroke.id)
    )) ?? [];
    const receiptedPendingBatch = pendingBatch && snapshotEligiblePendingStrokes.length > 0
      ? { pageId: pendingBatch.pageId, strokes: snapshotEligiblePendingStrokes }
      : null;
    const durablePages = resolveStudioDurableProjectPages({
      pagesHistory: pagesHistoryRef.current,
      historyIndex: pagesHiRef.current,
      fallbackPages: pages,
      pendingStrokeCommits: receiptedPendingBatch
        ? { pageId: receiptedPendingBatch.pageId, strokes: receiptedPendingBatch.strokes }
        : null,
    }).pagesList as PageState[];
    return buildCurrentStudioProjectFileSnapshot(
      durablePages,
      new Date().toISOString(),
      options.recoveredMasterStroke
    );
  }

  // The empty-dependency page lifecycle listeners below call through this ref, so every render
  // supplies the latest document/scope snapshot without reinstalling global handlers. This is a
  // best-effort durable recovery request; normal editing still uses the debounced autosave.
  persistPendingStrokeEmergencyAutosaveRef.current = (reason) => {
    const pendingBatch = pendingStrokeCommitsRef.current;
    const activeRecovery = readActiveStrokeLifecycleRecovery();
    const recoveredActiveStroke = activeRecovery.recovery.action === "recover"
      ? activeRecovery.recovery.pending.strokes.at(-1) ?? null
      : null;
    const effectivePendingBatch = recoveredActiveStroke && !activeRecovery.recoveringMaster
      ? activeRecovery.recovery.action === "recover"
        ? activeRecovery.recovery.pending
        : pendingBatch
      : pendingBatch;
    const receiptEligiblePendingStrokes = effectivePendingBatch?.strokes.filter((stroke) => (
      !selectedGpuStrokeRequiresFinalReceipt(stroke.id)
      || hasExactSelectedGpuFinalReceipt(stroke.id)
    )) ?? [];
    const durableEffectivePendingBatch = effectivePendingBatch
      && receiptEligiblePendingStrokes.length > 0
      ? { pageId: effectivePendingBatch.pageId, strokes: receiptEligiblePendingStrokes }
      : null;
    const recoveredActiveStrokeEligible = recoveredActiveStroke
      && (
        !selectedGpuStrokeRequiresFinalReceipt(recoveredActiveStroke.id)
        || hasExactSelectedGpuFinalReceipt(recoveredActiveStroke.id)
      )
      ? recoveredActiveStroke
      : null;
    const effectiveMasterStrokeCandidate =
      activeRecovery.recoveringMaster && recoveredActiveStrokeEligible
        ? recoveredActiveStrokeEligible
        : lifecycleMasterStrokeRecoveryRef.current;
    const effectiveMasterStroke = effectiveMasterStrokeCandidate
      && (
        !selectedGpuStrokeRequiresFinalReceipt(effectiveMasterStrokeCandidate.id)
        || hasExactSelectedGpuFinalReceipt(effectiveMasterStrokeCandidate.id)
      )
      ? effectiveMasterStrokeCandidate
      : null;
    const pagePendingFingerprint = durableEffectivePendingBatch?.strokes.length
      ? `${durableEffectivePendingBatch.pageId}:${durableEffectivePendingBatch.strokes.map((stroke) => stroke.id).join(",")}`
      : "";
    const activePendingFingerprint = recoveredActiveStrokeEligible
      ? studioActiveStrokeRecoveryFingerprint(recoveredActiveStrokeEligible)
      : "";
    const masterPendingFingerprint = effectiveMasterStroke
      ? `master:${effectiveMasterStroke.id}`
      : "";
    const pendingFingerprint = [
      pagePendingFingerprint,
      masterPendingFingerprint,
      activePendingFingerprint,
    ]
      .filter(Boolean)
      .join("|");
    const hasDirtyPendingState =
      pendingFingerprint !== studioLifecycleDurablePendingFingerprintRef.current;
    const hasDirtyStableState =
      studioRevisionProjectGenerationRef.current
      > studioLifecycleDurableGenerationRef.current;
    if (!hasDirtyPendingState && !hasDirtyStableState) return;
    if (!workHydrated || collaborationDocumentLocked) return;
    if (autosaveDocumentLeaseRef.current?.role === "follower") return;
    // A shared route must carry the exact hydrated revision. Treating a not-yet-hydrated work as
    // local would create a recovery that can never pass shared compatibility checks.
    if (workId && !sharedDocument) return;
    try {
      const savedAt = new Date().toISOString();
      const snapshot = currentStudioProjectSnapshot({
        pendingStrokeCommits: durableEffectivePendingBatch,
        recoveredMasterStroke: effectiveMasterStroke,
      });
      const stablePages = resolveStudioDurableProjectPages({
        pagesHistory: pagesHistoryRef.current,
        historyIndex: pagesHiRef.current,
        fallbackPages: pages,
        pendingStrokeCommits: null,
      }).pagesList as PageState[];
      const basePayload: StudioAutosavePayload = {
        ...snapshot,
        savedAt,
        // The lifecycle builder projects the batch itself so its receipt can distinguish stable
        // state from still-deferred vector data. Read the latest ref-backed history, not the render.
        pagesList: stablePages,
        ...(workId && sharedDocument
          ? { sourceWorkId: workId, sourceRevision: sharedDocument.revision }
          : {}),
      };
      const emergency = createStudioLifecycleEmergencyAutosave({
        payload: basePayload,
        pending: durableEffectivePendingBatch
          ? {
              pageId: durableEffectivePendingBatch.pageId,
              strokes: durableEffectivePendingBatch.strokes,
            }
          : null,
        reason,
        savedAt,
        documentScope:
          workId && sharedDocument
            ? { kind: "shared", workId, revision: sharedDocument.revision }
            : { kind: "local" },
      });
      if (emergency.ok) {
        const emergencyGeneration = studioRevisionProjectGenerationRef.current;
        const durableWrites: Promise<"opfs-journal" | "sqlite-fallback">[] = [];
        const sessionPromise = autosaveOpfsSessionRef.current;
        if (sessionPromise) {
          durableWrites.push(sessionPromise.then(async (session) => {
            if (!session) throw new Error("OPFS autosave authority is unavailable");
            const receipt = await session.write(emergency.payload);
            return receipt.authority;
          }));
        }
        const sqlitePromise = autosaveSqliteStoreRef.current;
        if (sqlitePromise) {
          durableWrites.push(sqlitePromise.then(async (acquiredSqlite) => {
            // persist 경로를 우회하는 옆문 ②. follower 탭의 pagehide 저장이 더 늦은 savedAt 으로
            // 선행 탭 문서를 덮는 유일한 실제 포크 경로였다.
            //
            // 가드는 마운트 때 잡아둔 것을 쓴다(동적 import 금지 — 그 한 홉이 pointerup 쓰기를
            // unload 뒤로 밀어낸다). 아직 못 잡았다면 세션도 안 열렸다는 뜻이라 임차권이 없고,
            // 임차권이 없으면 follower 일 수 없으므로 가드와 같은 판정(통과)이다.
            const applyLeadership = autosaveLeadershipGuardRef.current;
            const sqlite = applyLeadership
              ? applyLeadership(acquiredSqlite, autosaveDocumentLeaseRef.current)
              : acquiredSqlite;
            if (!sqlite) throw new Error("SQLite autosave authority is unavailable");
            await sqlite.write(autosaveKey, emergency.payload);
            return "sqlite-fallback" as const;
          }));
        }
        const durabilityAttempt = durableWrites.length > 0
          ? Promise.any(durableWrites)
          : Promise.reject(
              new Error("OPFS journal and SQLite autosave authorities are unavailable")
            );
        void durabilityAttempt
          .then((authority) => {
            studioLifecycleDurableGenerationRef.current = Math.max(
              studioLifecycleDurableGenerationRef.current,
              emergencyGeneration
            );
            studioLifecycleDurablePendingFingerprintRef.current = pendingFingerprint;
            noteStudioSaveSucceeded(authority);
          })
          .catch((cause: unknown) => {
            if (studioAutosaveDocumentBusy(cause)) return;
            // The exact payload remains in the current tab's memory. Do not advance either durable
            // frontier until an OPFS/SQLite receipt exists, and make the loss of durability visible.
            reportStudioSaveAuthorityDegraded(cause);
            void reportStudioAutosaveFailure(cause);
            console.error("Pending stroke emergency autosave failed:", cause);
          });
      }
    } catch (cause) {
      // pagehide/unmount must stay non-blocking. Keep a diagnostic for development without
      // throwing during browser teardown, where React cannot safely surface an error banner.
      console.error("Pending stroke emergency autosave failed:", cause);
    }
  };

  function applyStudioProjectSnapshotWithPreparedDocuments(
    projectData: StudioProjectFile,
    normalizeReleaseSchedule: (value: unknown) => StudioReleaseSchedule,
    publicationAnalyticsDocument: StudioPublicationAnalyticsDocument,
  ): boolean {
    if (!editorMountedRef.current) return false;
    if (documentSaveInFlightRef.current) {
      setError("저장 중에는 프로젝트를 교체할 수 없어요. 저장이 끝난 뒤 다시 시도해 주세요.");
      return false;
    }
    if (collaborationAccessRef.current.locked) {
      setError(collaborationLockMessage());
      return false;
    }
    if (!prepareStudioDocumentReplacement("프로젝트를 교체")) return false;
    setSharedDocumentNotice(null);
    const restoredPages = projectData.pagesList as PageState[];
    const currentHistory = pagesHistoryRef.current;
    const currentHistoryIndex = Math.max(
      0,
      Math.min(pagesHiRef.current, Math.max(0, currentHistory.length - 1))
    );
    const currentPages = currentHistory[currentHistoryIndex] ?? pages;
    const workAssetReason = studioWorkAssetDocumentSourceTransitionReason(
      currentPages,
      restoredPages
    );
    if (workAssetReason) {
      setError(workAssetReason);
      return false;
    }
    // Every replacement starts without import provenance. A successful canonical JSON import
    // installs its own detached envelope metadata after this transaction returns; legacy,
    // archive, checkpoint, and server restore paths intentionally leave the session cleared.
    studioProjectDocumentSessionRef.current = null;
    resetAdvancedFillForDocumentReplacement();
    // 히스토리에 새 페이지 상태를 추가해 JSON/복구 지점 복원도 ⌘Z 흐름과 충돌하지 않게 한다.
    const appended = appendStudioPagesHistorySnapshot(
      currentHistory,
      currentHistoryIndex,
      restoredPages
    );
    recordStudioHistoryTransition({
      mutationKind: "project.replace",
      previousPages: currentPages,
      nextPages: restoredPages,
      previousHistoryIndex: currentHistoryIndex,
      nextHistoryIndex: appended.historyIndex,
    });
    pagesHistoryRef.current = appended.history;
    pagesHiRef.current = appended.historyIndex;
    recordStudioHistoryJournalPages(1, appended.historyIndex);
    noteStudioHistoryRetention(appended);
    setPagesHistory(appended.history);
    setPagesHi(appended.historyIndex);
    setCurrentPageId(
      restoredPages.some((page) => page.id === projectData.currentPageId)
        ? projectData.currentPageId!
        : restoredPages[0].id
    );
    setTitle(projectData.title);
    setDescription(projectData.description);
    setTagsText(projectData.tagsText);
    setWebtoonTheme(projectData.webtoonTheme);
    setPanelGutter(projectData.panelGutter);
    const publishPack = normalizeStudioPublishPackSettings(projectData.publishPack);
    setPublishProfile(publishPack.profile);
    setPublishAiUsage(publishPack.aiUsage);
    setPublishAiDisclosure(publishPack.disclosure);
    setPublishCompliance(publishPack.compliance);
    setPublishPackageSettings(publishPackageSettingsFromPack(projectData.publishPack));
    setPublishPackageCredits(publishPackageCreditsFromPack(projectData.publishPack));
    setMaster(normalizeDocumentMaster(projectData.master) as DocumentMaster<El>);
    hydrateStudioSidecarDocuments({
      characterBible: normalizeStudioCharacterBible(projectData.characterBible),
      writerRoom: normalizeStudioWriterRoomDocument(projectData.writerRoom),
    });
    setAiProvenance(
      recoverInterruptedStudioAiOperations(
        normalizeStudioAiProvenanceDocument(projectData.aiProvenance)
      )
    );
    setStudioComments(normalizeStudioCommentsDocument(projectData.comments));
    setReleaseSchedule(normalizeReleaseSchedule(projectData.releaseSchedule));
    setPublicationAnalytics(publicationAnalyticsDocument);
    setReferenceBoard(normalizeStudioReferenceBoardDocument(projectData.referenceBoard));
    setScenarioImageReferenceDocument(
      hydrateStudioAiImageReferenceDocument(projectData.aiImageReferences),
    );
    return true;
  }

  async function applyStudioProjectSnapshot(projectData: StudioProjectFile): Promise<boolean> {
    const mutationTicket = captureStudioMutationTicket();
    const [
      { normalizeStudioReleaseSchedule },
      publicationAnalyticsDocument,
    ] = await Promise.all([
      loadStudioReleaseScheduleRuntime(),
      normalizeStudioPublicationAnalyticsDeferred(projectData.publicationAnalytics),
    ]);
    if (!canApplyStudioMutation(mutationTicket)) return false;
    return applyStudioProjectSnapshotWithPreparedDocuments(
      projectData,
      normalizeStudioReleaseSchedule,
      publicationAnalyticsDocument,
    );
  }

  const {
    checkpointPanelOpen,
    setCheckpointPanelOpen,
    checkpoints,
    checkpointError,
    saveNamedCheckpoint,
    createNamedCheckpoint,
    restoreNamedCheckpoint,
    removeNamedCheckpoint,
  } = useStudioCheckpoints({
    checkpointKey,
    pages,
    ensureSharedDocumentAvailableForExport,
    currentStudioProjectSnapshot,
    applyStudioProjectSnapshot,
    undo,
  });

  const [serverRevisions, setServerRevisions] = useState<WorkRevisionSummary[]>([]);
  const [serverRevisionLoading, setServerRevisionLoading] = useState(false);
  const [serverRevisionError, setServerRevisionError] = useState<string | null>(null);
  const serverRevisionRequestRef = useRef(0);
  useEffect(() => {
    if (!checkpointPanelOpen) return;
    if (!workId || !studioAuthUserId || !serverCurrentRevision || sharedDocument?.role !== "owner" || !loggedIn) {
      setServerRevisions([]);
      setServerRevisionError(null);
      setServerRevisionLoading(false);
      return;
    }
    const controller = new AbortController();
    const requestId = serverRevisionRequestRef.current + 1;
    serverRevisionRequestRef.current = requestId;
    const requestScope = { authScopeKey: studioAuthUserId, workId };
    const requestIsCurrent = () =>
      requestId === serverRevisionRequestRef.current &&
      isStudioEditorAsyncScopeCurrent(requestScope, {
        ...currentStudioDocumentScopeRef.current,
        mounted: editorMountedRef.current,
        aborted: controller.signal.aborted,
      });
    setServerRevisionLoading(true);
    setServerRevisionError(null);
    void import("@/src/infrastructure/creator-client")
      .then(({ listWorkRevisions }) => {
        if (!requestIsCurrent()) return null;
        return listWorkRevisions(workId, 20, controller.signal);
      })
      .then((revisions) => {
        if (revisions && requestIsCurrent()) setServerRevisions(revisions);
      })
      .catch((cause) => {
        if (!requestIsCurrent()) return;
        setServerRevisionError(cause instanceof Error ? cause.message : "서버 버전 목록을 불러오지 못했어요.");
      })
      .finally(() => {
        if (editorMountedRef.current && requestId === serverRevisionRequestRef.current) {
          setServerRevisionLoading(false);
        }
      });
    return () => {
      controller.abort();
    };
  }, [
    checkpointKey,
    checkpointPanelOpen,
    currentStudioDocumentScopeRef,
    editorMountedRef,
    loggedIn,
    serverCurrentRevision,
    sharedDocument?.role,
    studioAuthUserId,
    workId,
  ]);

  async function openOwnerFxPanel() {
    if (loadedWork && !sharedDocument) {
      setFxPanelOpen(true);
      return;
    }
    if (!workId || sharedDocument?.role !== "owner" || !studioAuthUserId || fxPanelLoading) return;
    if (loadedWork?.revision === sharedDocument.revision) {
      setFxPanelOpen(true);
      return;
    }
    ownerDetailAbortRef.current?.abort();
    const controller = new AbortController();
    ownerDetailAbortRef.current = controller;
    const request = { authScopeKey: studioAuthUserId, workId };
    const requestIsCurrent = () =>
      isStudioEditorAsyncScopeCurrent(request, {
        ...currentStudioDocumentScopeRef.current,
        mounted: editorMountedRef.current,
        aborted: controller.signal.aborted,
      });
    setFxPanelLoading(true);
    try {
      const { getWork } = await import("@/src/infrastructure/creator-client");
      if (!requestIsCurrent()) return;
      const detail = await getWork(workId, controller.signal);
      if (!requestIsCurrent()) return;
      if (detail.revision !== sharedDocument.revision) {
        setError("최신 공동 문서와 애니메이션 연출 데이터의 revision이 달라 다시 불러와야 해요.");
        return;
      }
      setLoadedWork(detail);
      setFxPanelOpen(true);
    } catch (cause) {
      if (requestIsCurrent()) {
        setError(cause instanceof Error ? cause.message : "애니메이션 연출을 불러오지 못했어요.");
      }
    } finally {
      if (ownerDetailAbortRef.current === controller) ownerDetailAbortRef.current = null;
      if (requestIsCurrent()) setFxPanelLoading(false);
    }
  }

  async function reloadServerRevisions() {
    if (!workId || !studioAuthUserId || !serverCurrentRevision || sharedDocument?.role !== "owner" || !loggedIn) {
      serverRevisionAbortRef.current?.abort();
      setServerRevisions([]);
      setServerRevisionError(null);
      return;
    }
    const requestId = serverRevisionRequestRef.current + 1;
    serverRevisionRequestRef.current = requestId;
    serverRevisionAbortRef.current?.abort();
    const controller = new AbortController();
    serverRevisionAbortRef.current = controller;
    const requestScope = { authScopeKey: studioAuthUserId, workId };
    const requestIsCurrent = () =>
      requestId === serverRevisionRequestRef.current &&
      isStudioEditorAsyncScopeCurrent(requestScope, {
        ...currentStudioDocumentScopeRef.current,
        mounted: editorMountedRef.current,
        aborted: controller.signal.aborted,
      });
    setServerRevisionLoading(true);
    setServerRevisionError(null);
    try {
      const { listWorkRevisions } = await import("@/src/infrastructure/creator-client");
      if (!requestIsCurrent()) return;
      const revisions = await listWorkRevisions(workId, 20, controller.signal);
      if (requestIsCurrent()) setServerRevisions(revisions);
    } catch (cause) {
      if (!requestIsCurrent()) return;
      setServerRevisionError(cause instanceof Error ? cause.message : "서버 버전 목록을 불러오지 못했어요.");
    } finally {
      if (serverRevisionAbortRef.current === controller) serverRevisionAbortRef.current = null;
      if (editorMountedRef.current && requestId === serverRevisionRequestRef.current) {
        setServerRevisionLoading(false);
      }
    }
  }

